original_checker='"""Independent literal recurrence, whole-output author checks and annual capital checks."""\nimport io, contextlib\n_buffer=io.StringIO()\nwith contextlib.redirect_stdout(_buffer):\n    exec(compile(\'#!/usr/bin/env python3\\n"""Independent literal recurrence: never imports production, never reads any input file.\\nReconstructs main endpoints and dominating -100bp earnings-margin counterexample.\\n"""\\nimport json\\n\\ndef value(r=.095,future=0.,shock=0.):\\n    # Order W,A,N,E,T,P is payout topology, unlike production dictionaries.\\n    capital=[.2,.05,1.337711799,.1,.20855,3.110002589]\\n    c=[.3,.5,.5,.84007771304,3.4,1.5]\\n    e=[.1,.25,-.98,.15,.8,.295361896472]\\n    s=[.01,.025,0.,.01,.05,.030272963548]\\n    scale=[.96,1.70,1.13,1.,6.65,.34]\\n    revenue0=[.943,1.636,1.081,.941,6.187,.333]\\n    floors=[.25,.3,.35,.4,2.5,.25]\\n    margin=[.07,.088,.025,.12,.062,-.28]\\n    own=[.39061845,.868041,1.,1.,.868041,1.]\\n    wcint=[.12,.12,.25,.25,.08,.05]\\n    weights=[0.,.006,.094,0.,.64,.26]\\n    rdweight=[0.,0.,0.,0.,.7,.3]\\n    maint=[.02,.025,.035,.005,.1,.025]\\n    asset=[0.]*6;loan=[0.]*6;loan[2]=.06154493196;debt=0.;ar=.12168522723;d=[];equity=7.10967444401-.0886183;ri=[]\\n    states=[]\\n    for t in range(1,301):\\n        growth=1.035**min(t-1,4)*1.025**max(0,min(t-5,5))*1.01**max(0,t-10)\\n        rev=[a*growth for a in scale]\\n        floor=[a*growth for a in floors];floor[5]+=.0886183\\n        mp=[m+((future if i<5 else future*2.5) if t>5 else 0.)+(shock if i<5 else 0.) for i,m in enumerate(margin)]\\n        rd=[0.,0.,0.,0.,.56678*.5/4*(t<=4),.25337*.5/4*(t<=4)]\\n        pjt=[0.,0.,(.153-.0273691)/3*(t<=3),0.,.8213258/3*(t<=3)+(.56678*.5+.135)/4*(t<=4),(.25337*.5+.2693959-.0352703)/4*(t<=4)]\\n        np=[rev[i]*mp[i]-.85*rd[i]+.012*max(c[i]-floor[i],0.) for i in range(6)]\\n        for i in range(5):\\n            x=loan[i]*.03;np[i]-=x;np[5]+=x\\n        np[5]-=debt*.05\\n        for i in range(6):\\n            delta=(rev[i]-revenue0[i])*wcint[i]\\n            delta+={1:.12,2:-.06,3:-.06}.get(t,0.)*([0,0,.1,.3,.6,0][i])\\n            legacy=(.04152088481*(t==1)+.00683172665/4*(t<=4)+.04447081124/5*(t<=5)+.18024890961/15*(t<=15))\\n            delta+=legacy*([0,0,0,0,.7,.3][i])\\n            c[i]+=np[i]-pjt[i]-delta\\n            asset[i]+=pjt[i]\\n        for i in [4,0,1,2,3]:\\n            borrowing=max(floor[i]-c[i],0.);c[i]+=borrowing;c[5]-=borrowing;loan[i]+=borrowing\\n            pay=min(loan[i],max(c[i]-floor[i],0.)/2);loan[i]-=pay;c[i]-=pay;c[5]+=pay\\n        prior=min(ar,max(c[4]-floor[4],0.));ar-=prior;c[4]-=prior;c[5]+=prior\\n        profit=np[:];paid=[]\\n        for i in range(6):\\n            if i==5:\\n                debtadd=max(floor[5]-c[5],0.);debt+=debtadd;c[5]+=debtadd\\n                pay=min(debt,max(c[5]-floor[5],0.));debt-=pay;c[5]-=pay\\n                request=max(sum(np[j]*own[j] for j in range(6)),0.)*[.1,.15,.2,.25,.3][t-1] if t<=5 else max(c[i]-floor[i],0.)*min(1.,.4+.15*(t-6))\\n                if debt>1e-10:request=0.\\n            else:request=max(c[i]-floor[i],0.)*(.3 if t<=5 else min(1.,.45+.15*(t-6)))\\n            restored=min(max(profit[i],0.),max(-e[i],0.))\\n            reserve=min(.1*max(profit[i]-restored,0.),max(.5*capital[i]-s[i],0.))\\n            e[i]+=profit[i]-reserve;s[i]+=reserve\\n            p=max(0.,min(request,max(e[i],0.),max(c[i]-floor[i],0.)))\\n            e[i]-=p;c[i]-=p;paid.append(p)\\n            if i==0:c[4]+=.45*p;profit[4]+=.45*p\\n            if i==1:c[4]+=p;profit[4]+=p\\n            if i in (2,3,4):\\n                f=.868041 if i==4 else 1.;c[5]+=p*f;profit[5]+=p*f\\n        ep=sum(np[j]*own[j] for j in range(6));ri.append(ep-r*equity);equity+=ep-paid[5]\\n        d.append(paid[5]/3.110002589);revenue0=rev\\n        if t==5:states=[c[:],e[:],s[:],loan[:],equity]\\n    tail=d[-1]*1.01/(r-.01)\\n    pv=sum(x/(1+r)**(i+1) for i,x in enumerate(d))+tail/(1+r)**300\\n    tv=sum(x/(1+r)**(i-4) for i,x in enumerate(d[5:],start=5))+tail/(1+r)**295\\n    return {\\\'value\\\':pv,\\\'tv5\\\':tv,\\\'first5\\\':d[:5],\\\'year5_state\\\':states}\\n\\nanswer={k:value(*v) for k,v in {\\\'base\\\':(.095,0.,0.),\\\'core_low\\\':(.10,-.004,0.),\\\'core_high\\\':(.09,.004,0.),\\\'margin_minus1pp\\\':(.095,0.,-.01)}.items()}\\nassert answer[\\\'margin_minus1pp\\\'][\\\'value\\\']<answer[\\\'base\\\'][\\\'value\\\']\\nassert answer[\\\'core_low\\\'][\\\'first5\\\']==answer[\\\'base\\\'][\\\'first5\\\']==answer[\\\'core_high\\\'][\\\'first5\\\']\\nassert answer[\\\'core_low\\\'][\\\'year5_state\\\']==answer[\\\'base\\\'][\\\'year5_state\\\']==answer[\\\'core_high\\\'][\\\'year5_state\\\']\\nprint(json.dumps(answer,sort_keys=True,separators=(\\\',\\\',\\\':\\\')))\\n\', __file__, "exec"), {"__file__":__file__,"__name__":"__main__"})\nprint(_buffer.getvalue())\nexec(compile(\'#!/usr/bin/env python3\\n"""Stdlib verification; never mutates frozen report/model. Run from any cwd."""\\nimport json,hashlib,subprocess,sys,tempfile,shutil\\nfrom pathlib import Path\\nroot=Path(__file__).resolve().parent\\nrun=lambda p,cwd:subprocess.check_output([sys.executable,str(p)],cwd=cwd)\\na=run(root/\\\'2026-Q3.py\\\',root)\\nassert a==(root/\\\'2026-Q3-output.json\\\').read_bytes(),\\\'frozen stdout differs\\\'\\nwith tempfile.TemporaryDirectory() as d:\\n p=Path(d)/\\\'model.py\\\';shutil.copyfile(root/\\\'2026-Q3.py\\\',p)\\n assert run(p,d)==a,\\\'single-file different-cwd byte mismatch\\\'\\nb=_AUTHOR_JSON.encode()\\nassert hashlib.sha256(b).hexdigest()==\\\'4150c5038100f3f739ae987fbc8cb5a9b2d2d645af2f75841eabc37fecf2b331\\\'\\nj=json.loads(a);literal=json.loads(b)\\nfor name,lit in literal.items():\\n prod=j[\\\'cases\\\'][name]\\n assert abs(lit[\\\'value\\\']-prod[\\\'value\\\'])<1e-10\\n assert abs(lit[\\\'tv5\\\']-prod[\\\'year5_terminal\\\'])<1e-10\\n for x,y in zip(lit[\\\'first5\\\'],prod[\\\'first5\\\']):assert abs(x-y)<1e-10\\nfor name,c in j[\\\'cases\\\'].items():\\n assert len(c[\\\'years\\\'])==300\\n assert c[\\\'horizon_300_500_absolute_difference\\\']<1e-8\\n for row in c[\\\'years\\\']:\\n  assert row[\\\'external_debt_end\\\']<1e-9\\n  assert sum(row[\\\'internal_loans_end\\\'].values())<=.25+1e-9\\ncandidate=json.loads(\\\'{"return_model": {"schema_version": 1, "method": "annual_common_equity_irr_v1", "currency": "CNY", "model_as_of": "2026-10-28T16:16:00+00:00", "base_case_distributions_per_share": [0.016738, 0.025871, 0.035707, 0.046202, 0.065255], "base_case_terminal_equity_value_range_per_share": {"year_5": {"low": 2.273998, "high": 2.918916}}}, "value_range": {"low": 1.55, "high": 2.04, "currency": "CNY"}, "information_cutoff": "2026-10-28T16:16:00+00:00"}\\\')\\nrm=candidate[\\\'return_model\\\']\\nassert j[\\\'model_as_of\\\']==candidate[\\\'information_cutoff\\\']==rm[\\\'model_as_of\\\']\\nassert rm[\\\'base_case_distributions_per_share\\\']==[round(x,6) for x in j[\\\'cases\\\'][\\\'base\\\'][\\\'first5\\\']]\\ny5=rm[\\\'base_case_terminal_equity_value_range_per_share\\\'][\\\'year_5\\\']\\nassert y5=={\\\'low\\\':round(j[\\\'cases\\\'][\\\'core_low\\\'][\\\'year5_terminal\\\'],6),\\\'high\\\':round(j[\\\'cases\\\'][\\\'core_high\\\'][\\\'year5_terminal\\\'],6)}\\nassert candidate[\\\'value_range\\\']=={\\\'low\\\':1.55,\\\'high\\\':2.04,\\\'currency\\\':\\\'CNY\\\'}\\nprint(json.dumps({\\\'status\\\':\\\'author_self_check_pass_not_final_acceptance\\\',\\\'production_all_scenarios_annual_assertions\\\':True,\\\'scenarios\\\':len(j[\\\'cases\\\']),\\\'years_each\\\':300,\\\'additional_horizon\\\':500,\\\'isolated_single_py_stdout_byte_equal\\\':True,\\\'stdout_bytes\\\':len(a),\\\'stdout_sha256\\\':hashlib.sha256(a).hexdigest(),\\\'literal_cases\\\':list(literal),\\\'literal_tolerance\\\':1e-10,\\\'accepted_candidate_numeric_contract_match\\\':True},ensure_ascii=False,sort_keys=True,indent=2))\\n\', __file__, "exec"), {"__file__":__file__,"__name__":"__main__","_AUTHOR_JSON":_buffer.getvalue()})\nexec(compile("import json,sys,importlib.util\\nfrom decimal import Decimal as D\\nfrom pathlib import Path\\np=Path(__file__).resolve().parent\\nj=json.loads((p/\'2026-Q3-output.json\').read_text())\\ndef near(a,b):\\n assert abs(a-b)<=1e-9+1e-8*max(abs(a),abs(b)),(a,b)\\nown={\'P\':1.,\'T\':.868041,\'W\':.39061845,\'A\':.868041,\'N\':1.,\'E\':1.}\\ncash0={\'P\':D(\'1.5\'),\'T\':D(\'3.4\'),\'W\':D(\'.3\'),\'A\':D(\'.5\'),\'N\':D(\'.5\'),\'E\':D(\'.84007771304\')}\\nfloor={\'P\':D(\'.3386183\'),\'T\':D(\'2.5\'),\'W\':D(\'.25\'),\'A\':D(\'.3\'),\'N\':D(\'.35\'),\'E\':D(\'.4\')}\\nrev={\'P\':D(\'.34\'),\'T\':D(\'6.65\'),\'W\':D(\'.96\'),\'A\':D(\'1.7\'),\'N\':D(\'1.13\'),\'E\':D(\'1\')}\\nm={\'P\':D(\'-.28\'),\'T\':D(\'.062\'),\'W\':D(\'.07\'),\'A\':D(\'.088\'),\'N\':D(\'.025\'),\'E\':D(\'.12\')}\\nni={k:rev[k]*m[k]+max(D(0),cash0[k]-floor[k])*D(\'.012\') for k in rev}\\nni[\'P\']-=D(\'.25337\')*D(\'.5\')/4*D(\'.85\');ni[\'T\']-=D(\'.56678\')*D(\'.5\')/4*D(\'.85\')\\nni[\'N\']-=D(\'.06154493196\')*D(\'.03\');ni[\'P\']+=D(\'.06154493196\')*D(\'.03\')\\nfor k in ni:near(float(ni[k]),j[\'cases\'][\'base\'][\'years\'][0][\'normalized_external_net_profit\'][k])\\nfor name,c in j[\'cases\'].items():\\n oldcash=7.04007771304;oldcommon=7.10967444401-.0886183;oldnci=.67573196051;olddebt=0\\n for r in c[\'years\']:\\n  external=r[\'normalized_external_net_profit\'];paid=r[\'actual_paid\'];profit=sum(external.values());cash=sum(r[\'cash_end\'].values());common=r[\'ordinary_equity_end\'];nci=r[\'minority_equity_end\'];debt=r[\'external_debt_end\'];imp=r[\'noncash_asset_impairment\']\\n  near(r[\'ordinary_profit\'],sum(external[k]*own[k] for k in own));near(r[\'minority_paid\'],paid[\'W\']*.55+paid[\'T\']*.131959)\\n  near(cash,oldcash+profit+imp+sum(r[\'depreciation\'].values())-sum(r[\'capex\'].values())-sum(r[\'change_working_capital\'].values())-paid[\'P\']-r[\'minority_paid\']+debt-olddebt)\\n  near(common,oldcommon+r[\'ordinary_profit\']-paid[\'P\']);near(nci,oldnci+profit-r[\'ordinary_profit\']-r[\'minority_paid\'])\\n  near(cash+r[\'net_non_cash_operating_capital_end\']-debt,common+nci+.0886183)\\n  for k in own:\\n   near(r[\'re_end\'][k],r[\'opening_re\'][k]+r[\'legal_profit_including_new_declarations\'][k]-r[\'reserve_appropriation\'][k]-paid[k]);near(r[\'reserve_end\'][k],r[\'opening_reserve\'][k]+r[\'reserve_appropriation\'][k])\\n   assert r[\'cash_end\'][k]>=r[\'operating_cash_floor\'][k]-1e-9\\n  assert debt<1e-9 and sum(r[\'internal_loans_end\'].values())<=.25+1e-9\\n  oldcash,oldcommon,oldnci,olddebt=cash,common,nci,debt\\n assert c[\'horizon_300_500_absolute_difference\']<1e-8\\nfor n in [\'core_low\',\'core_high\']:\\n assert j[\'cases\'][n][\'years\'][:5]==j[\'cases\'][\'base\'][\'years\'][:5] or j[\'cases\'][n][\'first5\']==j[\'cases\'][\'base\'][\'first5\']\\n # Residual income depends on discount rate; real state must not.\\n for f in [\'cash_end\',\'re_end\',\'reserve_end\',\'internal_loans_end\',\'ordinary_equity_end\',\'minority_equity_end\']:\\n  assert j[\'cases\'][n][\'years\'][4][f]==j[\'cases\'][\'base\'][\'years\'][4][f]\\nspec=importlib.util.spec_from_file_location(\'subject\',p/\'2026-Q3.py\');mod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)\\na=mod.payment(-5,0,100,3,20,1,99);assert a[\'re\']==-2 and a[\'paid\']==0 and a[\'reserve\']==0\\nb=mod.payment(-5,0,100,10,20,1,99);near(b[\'paid\'],4.5);near(b[\'reserve\'],.5)\\nc=mod.payment(0,49,100,30,50,1,99);near(c[\'reserve\'],50);near(c[\'paid\'],29)\\nprint(json.dumps({\'status\':\'pass\',\'cases\':len(j[\'cases\']),\'complete_years_each\':300,\'own_decimal_y1_external_profit\':{k:str(v) for k,v in ni.items()},\'all_year_cash_equity_legal_minorities\':True,\'same_base_y5\':True,\'production_loss_first_and_cap_fixtures\':True},indent=2))\\n", __file__, "exec"), {"__file__":__file__,"__name__":"__main__","_AUTHOR_JSON":_buffer.getvalue()})\n'
with tempfile.TemporaryDirectory(prefix='q3-lossless-full-')as tmp:
    target=Path(tmp);source=here/'2026-Q3-output.json';raw=target/'2026-Q3-output.json'
    assert source.is_file() and not source.is_symlink()
    if source.stat().st_size<=4096:
        meta=json.loads(source.read_text());assert meta==expected
        assert meta['schema']=='trading_os_lossless_json_xz_v1' and meta['artifact_kind']=='transport_manifest_not_model_result'
        assert meta['compression']=='xz' and meta['file']=='2026-Q3-output.json.xz' and meta['expanded_media_type']=='application/json'
        assert 0<meta['compressed_bytes']<=100*1024**2 and 0<meta['expanded_bytes']<=512*1024**2
        zipped=here/meta['file'];assert zipped.is_file() and not zipped.is_symlink() and zipped.resolve().parent==here.resolve()
        assert zipped.stat().st_size==meta['compressed_bytes']
        with zipped.open('rb')as f:assert hashlib.file_digest(f,'sha256').hexdigest()==meta['compressed_sha256']
        dec=lzma.LZMADecompressor(format=lzma.FORMAT_XZ,memlimit=256*1024**2);total=0
        with zipped.open('rb')as inp,raw.open('wb')as out:
            while chunk:=inp.read(65536):
                assert not dec.eof
                block=dec.decompress(chunk,max_length=1048576)
                while True:
                    total+=len(block);assert total<=meta['expanded_bytes'];out.write(block)
                    if dec.eof or dec.needs_input:break
                    block=dec.decompress(b'',max_length=1048576)
            assert dec.eof and not dec.unused_data and total==meta['expanded_bytes']
    else:shutil.copyfile(source,raw)
    assert raw.stat().st_size==expected['expanded_bytes']
    with raw.open('rb')as f:assert hashlib.file_digest(f,'sha256').hexdigest()==expected['expanded_sha256']
    model=here/'2026-Q3.py';assert model.is_file() and not model.is_symlink();shutil.copyfile(model,target/'2026-Q3.py')
    checker=target/'2026-Q3-independent-recompute.py';checker.write_text(original_checker)
    subprocess.run([sys.executable,'-I','-S',str(checker)],cwd=target,check=True)
